<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Invalid credentials&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Skips hashing: finishes in 4ms</span></span>
